#!/usr/bin/env bash
# gos-map:fn bin/lib/map/allowlist.cjs#fn:initAllowlist
# gos-map:cmd map
# require-allowlist v2 productization — generic (non-GOS-layout) module
# inference, init command lifecycle, gate v2 assertion. Single truth source:
# .gos/codebase/require-allowlist.json (schema v2, generated by `gos map allowlist init`).
# Fixture pattern follows / : sandbox git repo → real scan → assertions.
T65_DIR=""

t65_setup() {
  T65_DIR="$TESTBASE/test-$(date +%s)-$RANDOM-t65"
  mkdir -p "$T65_DIR" && cd "$T65_DIR" || exit 1
}

t65_teardown() { cd "$TESTBASE" >/dev/null 2>&1; rm -rf "$T65_DIR"; }

# sandbox with two modules: mod-b/main.cjs requires mod-a/util.cjs (one cross edge).
# `gos init 1` seeds a local .gos/state.json so exec-class `gate` runs inside the
# sandbox instead of hitting the ancestor project-root guard.
t65_twomod_repo() {
  local dir="$1" name="$2"
  mkdir -p "$dir/lib/mod-a" "$dir/lib/mod-b"
  cd "$dir" || exit 1
  git init -q . && git commit -q --allow-empty -m root
  printf 'module.exports = {};\n' > lib/mod-a/util.cjs
  cat > lib/mod-b/main.cjs <<'B'
'use strict';
const util = require('../mod-a/util.cjs');
function mainRun() { return util; }
module.exports = { mainRun };
B
  git add -A && git commit -q -m fixture
  node "$GOS" init 1 "$name" >/dev/null 2>&1
}

t65_setup
echo "--- T65: require-allowlist v2 (generic module inference + init lifecycle) ---"

# --- .a: non-GOS layout sandbox: scan → init → gate direction assertion green
t65_twomod_repo "$T65_DIR/repo-a" "t65-a"
set +e; SOUT=$(node "$GOS" map scan 2>&1); SRC=$?; set -e
assert_exit "a1 scan exits 0" 0 "$SRC"
set +e; IOUT=$(node "$GOS" map allowlist init 2>&1); IRC=$?; set -e
assert_exit "a2 allowlist init exits 0" 0 "$IRC"
assert_file "a3 v2 file written" ".gos/codebase/require-allowlist.json"
python3 -c "
import json
d = json.load(open('.gos/codebase/require-allowlist.json'))
assert d['schema_version'] == 2, d
assert 'lib/mod-a' in d['moduleRoots'] and 'lib/mod-b' in d['moduleRoots'], d['moduleRoots']
dirs = {(x['from'], x['to']) for x in d['directions']}
assert ('lib/mod-b', 'lib/mod-a') in dirs, dirs
" && echo "  ✓ a4 v2 shape (roots + derived direction mod-b→mod-a)" || echo "  ✗ a4 v2 shape wrong"
set +e; GOUT=$(node "$GOS" gate all --audit 2>&1); GRC=$?; set -e
assert_exit "a5 gate all --audit exits 0 with v2 allowlist" 0 "$GRC"
assert_contains "a6 gate output shows direction assertion green" "require direction assertion green" "$GOUT"
HOUT=$(node "$GOS" help map 2>&1)
assert_contains "a7 help mentions allowlist init" "allowlist init" "$HOUT"

# --- .b: injected cross-module require → gate FAIL naming the violating edge
mkdir -p lib/mod-c
printf "const util = require('../mod-a/util.cjs');\nmodule.exports = { util };\n" > lib/mod-c/index.cjs
set +e; node "$GOS" map scan >/dev/null 2>&1; VOUT=$(node "$GOS" gate codemap 2>&1); VRC=$?; set -e
assert_exit "b1 gate codemap FAILs on cross-module violation" 1 "$VRC"
assert_contains "b2 violation names the edge + direction" "not in the allowlist" "$VOUT"
assert_contains "b3 violation names mod-c source" "mod-c" "$VOUT"

# --- .c: polluted tree + init --force → confirm listed; headless aborts, no write
t65_twomod_repo "$T65_DIR/repo-c" "t65-c"
node "$GOS" map scan >/dev/null 2>&1
node "$GOS" map allowlist init >/dev/null 2>&1
BEFORE=$(sha256sum .gos/codebase/require-allowlist.json | cut -d' ' -f1)
mkdir -p lib/mod-c
printf "const util = require('../mod-a/util.cjs');\nmodule.exports = { util };\n" > lib/mod-c/index.cjs
node "$GOS" map scan >/dev/null 2>&1
set +e; COUT=$(GOS_HEADLESS=1 node "$GOS" map allowlist init --force 2>&1); CRC=$?; set -e
assert_exit "c1 headless init --force aborts (would legitimize violation)" 1 "$CRC"
assert_contains "c2 abort lists the polluted edge" "mod-c" "$COUT"
assert_contains "c3 abort says nothing written" "headless" "$COUT"
AFTER=$(sha256sum .gos/codebase/require-allowlist.json | cut -d' ' -f1)
assert_eq "c4 allowlist file untouched" "$BEFORE" "$AFTER"

# --- .d: existing allowlist + init without --force refuses; --force diffs then writes
t65_twomod_repo "$T65_DIR/repo-d" "t65-d"
node "$GOS" map scan >/dev/null 2>&1
node "$GOS" map allowlist init >/dev/null 2>&1
set +e; DOUT=$(node "$GOS" map allowlist init 2>&1); DRC=$?; set -e
assert_exit "d1 init without --force on existing file refuses" 1 "$DRC"
assert_contains "d2 refusal points at --force" "\-\-force" "$DOUT"
set +e; FOUT=$(GOS_HEADLESS=1 node "$GOS" map allowlist init --force 2>&1); FRC=$?; set -e
assert_exit "d3 headless --force proceeds when nothing needs legitimizing" 0 "$FRC"
assert_contains "d4 force prints old-vs-new direction diff" "direction diff" "$FOUT"

# --- .e: hand-edited empty moduleRoots → gate FAIL
python3 -c "
import json
p = '.gos/codebase/require-allowlist.json'
d = json.load(open(p))
d['moduleRoots'] = []
json.dump(d, open(p, 'w'), indent=2)
"
set +e; EOUT=$(node "$GOS" gate codemap 2>&1); ERC=$?; set -e
assert_exit "e1 empty moduleRoots FAILs gate" 1 "$ERC"
assert_contains "e2 failure names moduleRoots problem" "moduleRoots" "$EOUT"

# --- .f: stale deps.json (file mutated after scan) → init refuses with scan hint
t65_twomod_repo "$T65_DIR/repo-f" "t65-f"
node "$GOS" map scan >/dev/null 2>&1
printf "const m = require('../mod-b/main.cjs');\nmodule.exports._m = m;\n" >> lib/mod-a/util.cjs
set +e; F2OUT=$(node "$GOS" map allowlist init 2>&1); F2RC=$?; set -e
assert_exit "f1 stale deps → init refuses" 1 "$F2RC"
assert_contains "f2 refusal embeds scan-first recovery" "map scan" "$F2OUT"
if [ -e .gos/codebase/require-allowlist.json ]; then echo "  ✗ f3 refusal wrote a file"; else echo "  ✓ f3 no allowlist written"; fi

# --- .g: legacy v1 file without bin/lib files → gate FAIL with migration line
t65_twomod_repo "$T65_DIR/repo-g" "t65-g"
node "$GOS" map scan >/dev/null 2>&1
mkdir -p .gos/codebase
cat > .gos/codebase/require-allowlist.json <<'V1'
{
  "rules": {
    "directions_module": [ { "from": "mod-b", "to": "mod-a" } ]
  }
}
V1
set +e; G2OUT=$(node "$GOS" gate codemap 2>&1); G2RC=$?; set -e
assert_exit "g1 v1 file in non-bin/lib repo FAILs" 1 "$G2RC"
assert_contains "g2 failure embeds migration command" "gos map allowlist init" "$G2OUT"

# --- .g2: v1 file WITH bin/lib shape but zero lib<->lib edges → vacuous-pass flag
t65_setup
mkdir -p "$T65_DIR/vac/bin/lib/mod-a" && cd "$T65_DIR/vac" || exit 1
git init -q . && git commit -q --allow-empty -m root
printf 'module.exports = {};\n' > bin/lib/mod-a/solo.cjs
git add -A && git commit -q -m vac
node "$GOS" init 1 "t65-vac" >/dev/null 2>&1
node "$GOS" map scan >/dev/null 2>&1
mkdir -p .gos/codebase
cat > .gos/codebase/require-allowlist.json <<'V1V'
{
  "rules": {
    "directions_module": [ { "from": "mod-a", "to": "mod-a" } ]
  }
}
V1V
set +e; GVOUT=$(node "$GOS" gate codemap 2>&1); GVRC=$?; set -e
assert_exit "g2a v1 vacuous pass exits 0 (advisory)" 0 "$GVRC"
assert_contains "g2b v1 vacuous pass flagged not silent green" "vacuous pass" "$GVOUT"

# --- .g3: v2 allowlist with real but edge-free moduleRoots → vacuous-pass flag
python3 - <<'PYV'
import json
doc = {"schema_version": 2, "moduleRoots": ["bin/lib/mod-a"], "directions": [{"from": "bin/lib/mod-a", "to": "bin/lib/mod-a"}], "generated_at": "test"}
json.dump(doc, open('.gos/codebase/require-allowlist.json', 'w'))
PYV
node "$GOS" map scan >/dev/null 2>&1
set +e; GV2OUT=$(node "$GOS" gate codemap 2>&1); GV2RC=$?; set -e
assert_exit "g3a v2 vacuous pass exits 0 (advisory)" 0 "$GV2RC"
assert_contains "g3b v2 vacuous pass flagged not silent green" "vacuous pass" "$GV2OUT"

# --- .h: zero-edge repo → init refuses to write
t65_setup
mkdir -p "$T65_DIR/solo/lib/only" && cd "$T65_DIR/solo" || exit 1
git init -q . && git commit -q --allow-empty -m root
printf 'module.exports = {};\n' > lib/only/x.cjs
git add -A && git commit -q -m solo
node "$GOS" map scan >/dev/null 2>&1
set +e; HOUT2=$(node "$GOS" map allowlist init 2>&1); HRC2=$?; set -e
assert_exit "h1 zero-edge init refuses" 1 "$HRC2"
assert_contains "h2 refusal says nothing to assert" "nothing to assert" "$HOUT2"
if [ -e .gos/codebase/require-allowlist.json ]; then echo "  ✗ h3 refusal wrote a file"; else echo "  ✓ h3 no allowlist written"; fi

# --- .i: gate output contains no self-repo phase numbering
set +e; IOUT2=$(cd "$GOS_ROOT" && node "$GOS" map scan >/dev/null 2>&1; node "$GOS" gate codemap 2>&1); IRC2=$?; set -e
assert_exit "i1 self-repo gate codemap green" 0 "$IRC2"
if printf '%s' "$IOUT2" | grep -q "Split-③"; then
  echo "  ✗ i2 gate output still contains self-repo phase numbering (Split-③)"; FAIL=$((FAIL+1))
else
  echo "  ✓ i2 gate output free of self-repo phase numbering"; PASS=$((PASS+1))
fi

t65_teardown
